    write_json(OUT/"copy_ssot.json",{"status":"COPY_READY","source":"Round 3J-D + Sarah Final Micro Patch","scenes":{"hero":"休みたい日もあれば、\nもっと知りたくなる日もある。","receive":"一日が終わっても、\n頭の中だけ切り替わらない日がある。","learn":"ヘッドスパを見ていて、\n「どうやっているんだろう」が残ったら。","healing":"分からないものは、\n分からないまま決めなくていい。","trust":"確認できること","action":"連絡する前に","ending":"ここまで読んで、\nひとつ確かめたいことが残ったら。"}})
