    write_json(OUT/"asset_manifest.json",{"assets":[{"path":"reproduction/assets/photography/generated/nagi_no_mirai/hero_treatment_space.png","scene":"S1","role":"abstract tactile / atmosphere","rights":"PROJECT_OWNED_GENERATED","evidence_authority":"NONE","surface_label":"イメージ"},{"path":"reproduction/assets/photography/generated/nagi_no_mirai/welcome_human.png","scene":"S3","role":"non-identifying human-scale detail","rights":"PROJECT_OWNED_GENERATED","evidence_authority":"NONE","surface_label":"イメージ"},{"path":"reproduction/assets/photography/generated/nagi_no_mirai/school_learning_context.png","scene":"S4","role":"learning / hand / object detail","rights":"PROJECT_OWNED_GENERATED","evidence_authority":"NONE","surface_label":"イメージ"},{"path":"reproduction/assets/material/middle-light.svg","scene":"S5","role":"abstract / translucent / uncertainty","rights":"PROJECT_AUTHORED","evidence_authority":"NONE","surface_label":"none"},{"path":"reproduction/assets/photography/generated/nagi_no_mirai/healing_consultation_context.png","scene":"S8","role":"open atmospheric material","rights":"PROJECT_OWNED_GENERATED","evidence_authority":"NONE","surface_label":"イメージ"}]})
